        self.inner.write(bytes);
    }

    fn write_u8(&mut self, value: u8) {
        self.inner.write_u8(value);
    }

    fn write_u16(&mut self, value: u16) {
        self.inner.write_u16(value);
    }

    fn write_u32(&mut self, value: u32) {
        self.inner.write_u32(value);
    }

    fn write_u64(&mut self, value: u64) {
        self.inner.write_u64(value);
    }

    fn write_usize(&mut self, value: usize) {
        self.inner.write_usize(value);
    }

    fn write_i8(&mut self, value: i8) {
        self.inner.write_i8(value);
    }

    fn write_i16(&mut self, value: i16) {
        self.inner.write_i16(value);
    }

    fn write_i32(&mut self, value: i32) {
        self.inner.write_i32(value);
    }

    fn write_i64(&mut self, value: i64) {
        self.inner.write_i64(value);
    }

    fn write_isize(&mut self, value: isize) {
        self.inner.write_isize(value);
    }

    fn write_u128(&mut self, value: u128) {
        self.inner.write_u128(value);
    }

    fn write_i128(&mut self, value: i128) {
        self.inner.write_i128(value);
    }
}

/// [`BuildHasher`] for [`MixingHasher`].
#[derive(Clone, Copy, Debug, Default)]
pub struct BuildMixingHasher;

impl BuildMixingHasher {
    pub fn new() -> BuildMixingHasher {
        BuildMixingHasher
    }
}

impl BuildHasher for BuildMixingHasher {
    type Hasher = MixingHasher;

    fn build_hasher(&self) -> MixingHasher {
        MixingHasher::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::hash::Hash;

    fn hash_of<T: Hash, B: BuildHasher>(builder: &B, value: &T) -> u64 {
        let mut hasher = builder.build_hasher();
        value.hash(&mut hasher);
        hasher.finish()
    }

    #[test]
    fn integers_hash_to_themselves() {
        let builder = BuildIdentityHasher::new();
        for value in [0i32, 1, 2, 7, 12345, i32::MAX] {
            assert_eq!(hash_of(&builder, &value), value as u64);
        }
        // Negative values keep the two's-complement bit pattern, exactly like
        // `static_cast<std::size_t>(x)` in libstdc++.
        assert_eq!(hash_of(&builder, &-1i32), u64::MAX);
    }

    #[test]
    fn strings_are_spread_by_fnv1a() {
        let builder = BuildIdentityHasher::new();
        assert_ne!(hash_of(&builder, &"alpha"), hash_of(&builder, &"beta"));
        assert_eq!(hash_of(&builder, &"alpha"), hash_of(&builder, &"alpha"));
    }

    #[test]
    fn mixing_hasher_spreads_low_bits() {
        let builder = BuildMixingHasher::new();
        // Keys that all share the low 12 bits must not share them after mixing.
        let masked: Vec<u64> = (0..8u64)
            .map(|i| hash_of(&builder, &(i << 12)) & 0xfff)
            .collect();
        let distinct: std::collections::BTreeSet<u64> = masked.iter().copied().collect();
        assert!(distinct.len() > 1, "mixing hasher failed to spread: {masked:?}");
    }
}

