//! The hopscotch-hashing table that backs [`HopscotchMap`](super::HopscotchMap).
//!
//! # Algorithm
//!
//! Hopscotch hashing is open addressing with a bounded lookup cost.  Every key
//! has a *home bucket* `h = hash(key) & (bucket_count - 1)`.  The entry itself
//! may live in any of the [`NEIGHBOURHOOD_SIZE`] slots starting at `h`, and the
//! home bucket keeps a bitmap (`neighbourhood`) whose bit `d` is set when the
//! slot `h + d` stores an entry belonging to `h`.
//!
//! * A lookup only ever inspects the bits set in the home bucket's bitmap, so
//!   it touches at most [`NEIGHBOURHOOD_SIZE`] slots — all inside one or two
//!   cache lines.
//! * An insertion linearly probes for a free slot.  If that slot is farther
//!   than the neighbourhood allows, the free slot is *hopped* backwards: an
//!   entry that sits between the free slot and its own home is relocated into
//!   the free slot, which frees its previous slot closer to `h`.  This repeats
//!   until the free slot is inside `h`'s neighbourhood.
//! * If no hop sequence succeeds the table grows (rehash into twice as many
//!   buckets), which spreads the offending cluster.  As a final fallback the
//!   entry goes into an unbounded overflow list, mirroring the overflow
//!   container of `tsl::hopscotch_hash`.  This guarantees that insertion always
//!   terminates, even for a pathological hasher that maps every key to the same
//!   bucket.
//!
//! The bucket array is allocated with `NEIGHBOURHOOD_SIZE - 1` extra slots past
//! `bucket_count` so neighbourhoods never wrap around the end of the array;
//! those trailing slots are valid storage but are never home buckets.
//!
//! # Positions
//!
//! Iteration and lookup results are expressed as a flat [`Pos`]: values below
//! `slots()` index the bucket array, values from `slots()` upwards index the
//! overflow list, and [`HopscotchHash::end_pos`] is one past the last of them.
//! A `Pos` plays the role of a C++ iterator; like a C++ iterator it is
//! invalidated by any operation that rehashes the table.

#![allow(dead_code)]

use std::hash::{BuildHasher, Hash, Hasher};

use super::hash::BuildIdentityHasher;

/// Number of slots (including the home bucket itself) an entry may occupy,
/// which is also the width of the neighbourhood bitmap.
pub const NEIGHBOURHOOD_SIZE: usize = 32;

/// Bucket count used for the first allocation; always a power of two.
pub const INITIAL_BUCKET_COUNT: usize = 16;

/// Default load factor at which the table doubles.
pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.9;

/// Upper bound on the linear probe for a free slot.  Keeps a single insertion
/// bounded even in a nearly full table; failing the probe just grows the table.
const MAX_PROBE_LENGTH: usize = 8 * NEIGHBOURHOOD_SIZE;

/// How often a single insertion may grow the table while trying to find a slot
/// inside the key's neighbourhood before giving up and using the overflow list.
const MAX_GROW_ATTEMPTS: usize = 2;

/// A flat position inside the table; see the [module docs](self#positions).
pub type Pos = usize;

/// One slot of the bucket array.
pub struct Bucket<K, V> {
    /// Bit `d` is set when slot `self + d` holds an entry homed at `self`.
    neighbourhood: u32,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    const fn vacant() -> Bucket<K, V> {
        Bucket {
            neighbourhood: 0,
            entry: None,
        }
    }

    /// True when this slot stores no entry.
    pub fn is_vacant(&self) -> bool {
        self.entry.is_none()
    }

    /// The stored key/value pair, if any.
    pub fn entry(&self) -> Option<&(K, V)> {
        self.entry.as_ref()
    }

    /// The raw neighbourhood bitmap of this bucket.
    pub fn neighbourhood(&self) -> u32 {
        self.neighbourhood
    }
}

/// An open-addressed hash table using hopscotch hashing.
pub struct HopscotchHash<K, V, S = BuildIdentityHasher> {
    /// `bucket_count + NEIGHBOURHOOD_SIZE - 1` slots, or empty when unallocated.
    buckets: Vec<Bucket<K, V>>,
    /// Entries that did not fit into any neighbourhood.
    overflow: Vec<(K, V)>,
    /// Number of home buckets; a power of two, or zero before first allocation.
    bucket_count: usize,
    len: usize,
    max_load_factor: f32,
    /// Cached `floor(bucket_count * max_load_factor)`.
    grow_at: usize,
    hash_builder: S,
}

impl<K, V> HopscotchHash<K, V, BuildIdentityHasher>
where
    K: Hash + Eq,
{
    /// An empty table that allocates on first insertion.
    pub fn new() -> HopscotchHash<K, V, BuildIdentityHasher> {
        HopscotchHash::with_hasher(BuildIdentityHasher::new())
    }

    /// An empty table sized to hold `capacity` entries without rehashing.
    pub fn with_capacity(capacity: usize) -> HopscotchHash<K, V, BuildIdentityHasher> {
        HopscotchHash::with_capacity_and_hasher(capacity, BuildIdentityHasher::new())
    }
}

impl<K, V> Default for HopscotchHash<K, V, BuildIdentityHasher>
where
    K: Hash + Eq,
{
    fn default() -> HopscotchHash<K, V, BuildIdentityHasher> {
        HopscotchHash::new()
    }
}

impl<K, V, S> HopscotchHash<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    /// An empty table using `hash_builder`.
    pub fn with_hasher(hash_builder: S) -> HopscotchHash<K, V, S> {
        HopscotchHash {
            buckets: Vec::new(),
            overflow: Vec::new(),
            bucket_count: 0,
            len: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            grow_at: 0,
            hash_builder,
        }
    }

    /// An empty table using `hash_builder`, sized for `capacity` entries.
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> HopscotchHash<K, V, S> {
        let mut table = HopscotchHash::with_hasher(hash_builder);
        table.reserve(capacity);
        table
    }

    /// Number of entries stored.
    pub fn len(&self) -> usize {
        self.len
    }

    /// True when no entry is stored.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Number of home buckets (a power of two, or zero when unallocated).
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    /// Number of slots in the bucket array, including the trailing overflow
    /// slack that keeps neighbourhoods from wrapping.
    pub fn slots(&self) -> usize {
        self.buckets.len()
    }

    /// Number of entries that did not fit into any neighbourhood.
    pub fn overflow_len(&self) -> usize {
        self.overflow.len()
    }

    /// Number of entries the table can hold before it grows.
    pub fn capacity(&self) -> usize {
        self.grow_at
    }

    /// `len / bucket_count`, or `0.0` while unallocated.
    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.len as f32 / self.bucket_count as f32
        }
    }

    /// The load factor above which the table doubles.
    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    /// Sets the growth threshold, rehashing immediately if already exceeded.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        assert!(
            max_load_factor > 0.0 && max_load_factor <= 1.0,
            "max_load_factor must be in (0.0, 1.0]"
        );
        self.max_load_factor = max_load_factor;
        self.grow_at = grow_threshold(self.bucket_count, max_load_factor);
        if self.bucket_count != 0 && self.len > self.grow_at {
            self.reserve(self.len);
        }
    }

    /// A reference to the table's hash builder.
    pub fn hasher(&self) -> &S {
        &self.hash_builder
    }

    /// Grows the table so `additional` more entries fit without a rehash.
    pub fn reserve(&mut self, additional: usize) {
        let wanted = self.len.saturating_add(additional);
        if wanted <= self.grow_at {
            return;
        }
        self.rehash(wanted);
    }

    /// Rehashes into the smallest power-of-two bucket count that can hold
    /// `min_entries` entries within the maximum load factor.
    pub fn rehash(&mut self, min_entries: usize) {
        let needed = min_entries.max(self.len);
        let mut bucket_count = INITIAL_BUCKET_COUNT;
        while grow_threshold(bucket_count, self.max_load_factor) < needed {
            bucket_count = bucket_count
                .checked_mul(2)
                .expect("hopscotch table bucket count overflowed usize");
        }
        if bucket_count != self.bucket_count {
            self.rehash_to(bucket_count);
        }
    }

    /// Removes every entry, keeping the allocated buckets.
    pub fn clear(&mut self) {
        for bucket in &mut self.buckets {
            bucket.neighbourhood = 0;
            bucket.entry = None;
        }
        self.overflow.clear();
        self.len = 0;
    }

    fn hash_of(&self, key: &K) -> u64 {
        let mut hasher = self.hash_builder.build_hasher();
        key.hash(&mut hasher);
        hasher.finish()
    }

    /// The home bucket of `key`; only valid once buckets are allocated.
    fn home_of(&self, key: &K) -> usize {
        debug_assert!(self.bucket_count.is_power_of_two());
        (self.hash_of(key) & (self.bucket_count as u64 - 1)) as usize
    }

    /// Position of `key`, or `None` when absent.
    pub fn find(&self, key: &K) -> Option<Pos> {
        if self.bucket_count != 0 {
            let home = self.home_of(key);
            let mut bits = self.buckets[home].neighbourhood;
            while bits != 0 {
                let offset = bits.trailing_zeros() as usize;
                if let Some((stored, _)) = self.buckets[home + offset].entry.as_ref() {
                    if stored == key {
                        return Some(home + offset);
                    }
                }
                bits &= bits - 1;
            }
        }
        // Only pathological hashers ever populate the overflow list, so this
        // scan is skipped entirely in the common case.
        for (index, (stored, _)) in self.overflow.iter().enumerate() {
            if stored == key {
                return Some(self.buckets.len() + index);
            }
        }
        None
    }

    /// True when `key` is present.
    pub fn contains_key(&self, key: &K) -> bool {
        self.find(key).is_some()
    }

    /// The value stored for `key`.
    pub fn get(&self, key: &K) -> Option<&V> {
        let pos = self.find(key)?;
        self.entry_at(pos).map(|entry| &entry.1)
    }

    /// A mutable reference to the value stored for `key`.
    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        let pos = self.find(key)?;
        self.entry_at_mut(pos).map(|entry| &mut entry.1)
    }

    /// The key/value pair stored for `key`.
    pub fn get_key_value(&self, key: &K) -> Option<(&K, &V)> {
        let pos = self.find(key)?;
        self.entry_at(pos).map(|entry| (&entry.0, &entry.1))
    }

    /// Inserts `key`/`value` unless `key` is already present.
    ///
    /// Mirrors `std::unordered_map::insert`: the returned flag is `true` when
    /// the entry was inserted and `false` when an equivalent key already
    /// existed, in which case the stored value is left untouched.  The returned
    /// [`Pos`] designates the entry for `key` either way.
    pub fn insert(&mut self, key: K, value: V) -> (Pos, bool) {
        if let Some(pos) = self.find(&key) {
            return (pos, false);
        }
        if self.bucket_count == 0 || self.len + 1 > self.grow_at {
            self.grow();
        }

        let entry = (key, value);
        for _ in 0..MAX_GROW_ATTEMPTS {
            let home = self.home_of(&entry.0);
            if let Some(slot) = self.free_slot_for(home) {
                self.buckets[home].neighbourhood |= 1u32 << (slot - home);
                self.buckets[slot].entry = Some(entry);
                self.len += 1;
                return (slot, true);
            }
            // The neighbourhood is saturated: a bigger table spreads it out.
            self.grow();
        }

        self.overflow.push(entry);
        self.len += 1;
        (self.buckets.len() + self.overflow.len() - 1, true)
    }

    /// Inserts `key`/`value`, overwriting any previous value.
    ///
    /// Mirrors `std::unordered_map::insert_or_assign`; the flag reports whether
    /// a new entry was created.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> (Pos, bool) {
        if let Some(pos) = self.find(&key) {
            if let Some(entry) = self.entry_at_mut(pos) {
                entry.1 = value;
            }
            return (pos, false);
        }
        self.insert(key, value)
    }

    /// Removes `key`, returning its value.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        self.remove_entry(key).map(|(_, value)| value)
    }

    /// Removes `key`, returning the whole pair.
    pub fn remove_entry(&mut self, key: &K) -> Option<(K, V)> {
        let pos = self.find(key)?;
        self.len -= 1;
        if pos < self.buckets.len() {
            let home = self.home_of(key);
            debug_assert!(pos >= home && pos - home < NEIGHBOURHOOD_SIZE);
            self.buckets[home].neighbourhood &= !(1u32 << (pos - home));
            self.buckets[pos].entry.take()
        } else {
            // `swap_remove` keeps the overflow list compact; overflow order is
            // unspecified anyway, exactly as in an unordered container.
            Some(self.overflow.swap_remove(pos - self.buckets.len()))
        }
    }

    /// Doubles the bucket count (or performs the first allocation).
    fn grow(&mut self) {
        let bucket_count = if self.bucket_count == 0 {
            INITIAL_BUCKET_COUNT
        } else {
            self.bucket_count
                .checked_mul(2)
                .expect("hopscotch table bucket count overflowed usize")
        };
        self.rehash_to(bucket_count);
    }

    /// Reallocates to exactly `bucket_count` home buckets and reinserts.
    fn rehash_to(&mut self, bucket_count: usize) {
        debug_assert!(bucket_count.is_power_of_two());

        let old_buckets = std::mem::replace(&mut self.buckets, new_buckets(bucket_count));
        let old_overflow = std::mem::take(&mut self.overflow);
        self.bucket_count = bucket_count;
        self.grow_at = grow_threshold(bucket_count, self.max_load_factor);
        self.len = 0;

        for bucket in old_buckets {
            if let Some(entry) = bucket.entry {
                self.place(entry);
            }
        }
        for entry in old_overflow {
            self.place(entry);
        }
    }

    /// Stores an entry known to be absent, without growing the table.
    ///
    /// Used while rehashing, where growing would recurse; entries that cannot
    /// reach their neighbourhood land in the overflow list instead.
    fn place(&mut self, entry: (K, V)) {
        let home = self.home_of(&entry.0);
        match self.free_slot_for(home) {
            Some(slot) => {
                self.buckets[home].neighbourhood |= 1u32 << (slot - home);
                self.buckets[slot].entry = Some(entry);
            }
            None => self.overflow.push(entry),
        }
        self.len += 1;
    }

    /// Finds a vacant slot inside `home`'s neighbourhood, hopping entries
    /// backwards as needed.  `None` when the neighbourhood cannot be freed.
    fn free_slot_for(&mut self, home: usize) -> Option<usize> {
        let mut slot = self.probe_for_vacant(home)?;
        while slot - home >= NEIGHBOURHOOD_SIZE {
            slot = self.hop_closer(slot)?;
        }
        Some(slot)
    }

    /// First vacant slot at or after `home`, within the probe limit.
    fn probe_for_vacant(&self, home: usize) -> Option<usize> {
        let end = self.buckets.len().min(home + MAX_PROBE_LENGTH);
        (home..end).find(|&slot| self.buckets[slot].is_vacant())
    }

    /// Moves some entry into the vacant `slot`, returning the slot it freed —
    /// always closer to the start of the array.  `None` when no entry within
    /// reach of `slot` can legally move into it.
    fn hop_closer(&mut self, slot: usize) -> Option<usize> {
        debug_assert!(self.buckets[slot].is_vacant());
        debug_assert!(slot >= NEIGHBOURHOOD_SIZE);

        // Candidate home buckets whose neighbourhood still reaches `slot`.
        let first_home = slot + 1 - NEIGHBOURHOOD_SIZE;
        for home in first_home..slot {
            if home >= self.bucket_count {
                break; // Trailing slack slots are never home buckets.
            }
            let distance = (slot - home) as u32;
            // Entries closer to `home` than `slot` is: those can move up.
            let reachable = self.buckets[home].neighbourhood & ((1u32 << distance) - 1);
            if reachable == 0 {
                continue;
            }
            let offset = reachable.trailing_zeros();
            let source = home + offset as usize;
            let entry = self.buckets[source]
                .entry
                .take()
                .expect("neighbourhood bitmap pointed at a vacant slot");
            self.buckets[slot].entry = Some(entry);
            self.buckets[home].neighbourhood &= !(1u32 << offset);
            self.buckets[home].neighbourhood |= 1u32 << distance;
            return Some(source);
        }
        None
    }

    /// One past the last valid position.
    pub fn end_pos(&self) -> Pos {
        self.buckets.len() + self.overflow.len()
    }

    /// Position of the first entry, or [`end_pos`](Self::end_pos) when empty.
    pub fn first_pos(&self) -> Pos {
        let mut pos = 0;
        while pos < self.buckets.len() && self.buckets[pos].is_vacant() {
            pos += 1;
        }
        pos
    }

    /// Position following `pos` in iteration order, clamped to `end_pos()`.
    pub fn pos_after(&self, pos: Pos) -> Pos {
        let end = self.end_pos();
        if pos >= end {
            return end;
        }
        let mut next = pos + 1;
        while next < self.buckets.len() && self.buckets[next].is_vacant() {
            next += 1;
        }
        next
    }

    /// The entry at `pos`, or `None` when `pos` is not a live position.
    pub fn entry_at(&self, pos: Pos) -> Option<&(K, V)> {
        if pos < self.buckets.len() {
            self.buckets[pos].entry.as_ref()
        } else {
            self.overflow.get(pos - self.buckets.len())
        }
    }

    /// The entry at `pos`, mutably.
    pub fn entry_at_mut(&mut self, pos: Pos) -> Option<&mut (K, V)> {
        if pos < self.buckets.len() {
            self.buckets[pos].entry.as_mut()
        } else {
            let index = pos - self.buckets.len();
            self.overflow.get_mut(index)
        }
    }

    /// The bucket array, for tests and introspection.
    pub fn buckets(&self) -> &[Bucket<K, V>] {
        &self.buckets
    }
}

/// Allocates a vacant bucket array with the trailing anti-wrap slack.
fn new_buckets<K, V>(bucket_count: usize) -> Vec<Bucket<K, V>> {
    let slots = bucket_count
        .checked_add(NEIGHBOURHOOD_SIZE - 1)
        .expect("hopscotch table slot count overflowed usize");
    let mut buckets = Vec::with_capacity(slots);
    for _ in 0..slots {
        buckets.push(Bucket::vacant());
    }
    buckets
}

/// `floor(bucket_count * max_load_factor)`, at least one for a live table.
fn grow_threshold(bucket_count: usize, max_load_factor: f32) -> usize {
    if bucket_count == 0 {
        return 0;
    }
    let threshold = (bucket_count as f64 * max_load_factor as f64) as usize;
    threshold.max(1)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::tsl::hash::BuildMixingHasher;
    use std::collections::BTreeSet;
    use std::hash::{BuildHasher, Hasher};

    /// Every key lands in bucket zero: forces hops, growth and overflow.
    #[derive(Clone, Copy, Default)]
    struct BuildConstantHasher;

    #[derive(Default)]
    struct ConstantHasher;

    impl Hasher for ConstantHasher {
        fn finish(&self) -> u64 {
            0
        }
        fn write(&mut self, _bytes: &[u8]) {}
        fn write_i32(&mut self, _value: i32) {}
    }

    impl BuildHasher for BuildConstantHasher {
        type Hasher = ConstantHasher;
        fn build_hasher(&self) -> ConstantHasher {
            ConstantHasher
        }
    }

    fn collect_keys<K: Copy + Ord, V, S>(table: &HopscotchHash<K, V, S>) -> BTreeSet<K> {
        let mut keys = BTreeSet::new();
        let mut pos = table.first_pos();
        while pos != table.end_pos() {
            keys.insert(table.entry_at(pos).expect("live position").0);
            pos = table.pos_after(pos);
        }
        keys
    }

    #[test]
    fn empty_table_allocates_nothing() {
        let table: HopscotchHash<i32, i32> = HopscotchHash::new();
        assert_eq!(table.len(), 0);
        assert_eq!(table.bucket_count(), 0);
        assert_eq!(table.slots(), 0);
        assert_eq!(table.first_pos(), table.end_pos());
        assert!(table.find(&0).is_none());
    }

    #[test]
    fn insert_then_find() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::new();
        for i in 0..100 {
            let (_, inserted) = table.insert(i, i * 12);
            assert!(inserted);
        }
        assert_eq!(table.len(), 100);
        for i in 0..100 {
            assert_eq!(table.get(&i), Some(&(i * 12)));
        }
        assert!(table.get(&100).is_none());
        assert!(table.get(&-1).is_none());
    }

    #[test]
    fn insert_does_not_overwrite() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::new();
        let (first, inserted) = table.insert(7, 84);
        assert!(inserted);
        let (again, inserted) = table.insert(7, -1);
        assert!(!inserted);
        assert_eq!(first, again);
        assert_eq!(table.get(&7), Some(&84));
        assert_eq!(table.len(), 1);

        let (_, inserted) = table.insert_or_assign(7, -1);
        assert!(!inserted);
        assert_eq!(table.get(&7), Some(&-1));
        assert_eq!(table.len(), 1);
    }

    #[test]
    fn growth_preserves_every_entry() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::new();
        for i in 0..10_000 {
            table.insert(i, i);
        }
        assert_eq!(table.len(), 10_000);
        assert!(table.bucket_count() >= 10_000);
        assert!(table.load_factor() <= table.max_load_factor());
        assert_eq!(collect_keys(&table), (0..10_000).collect::<BTreeSet<i32>>());
    }

    #[test]
    fn negative_and_sparse_keys() {
        let mut table: HopscotchHash<i64, i64> = HopscotchHash::new();
        let keys: Vec<i64> = vec![-1, -2, i64::MIN, i64::MAX, 0, 1 << 40, -(1 << 40)];
        for &key in &keys {
            table.insert(key, key * 3);
        }
        assert_eq!(table.len(), keys.len());
        for &key in &keys {
            assert_eq!(table.get(&key), Some(&key.wrapping_mul(3)));
        }
    }

    #[test]
    fn string_keys_use_the_byte_fallback() {
        let mut table: HopscotchHash<String, usize> = HopscotchHash::new();
        for (index, word) in ["alpha", "beta", "gamma", "delta"].iter().enumerate() {
            table.insert(word.to_string(), index);
        }
        assert_eq!(table.get(&"gamma".to_string()), Some(&2));
        assert!(table.get(&"epsilon".to_string()).is_none());
    }

    #[test]
    fn removal_frees_the_neighbourhood_bit() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::new();
        for i in 0..64 {
            table.insert(i, i);
        }
        for i in (0..64).step_by(2) {
            assert_eq!(table.remove(&i), Some(i));
        }
        assert_eq!(table.len(), 32);
        for i in 0..64 {
            assert_eq!(table.get(&i), if i % 2 == 0 { None } else { Some(&i) });
        }
        // Re-inserting the removed keys must work and reuse the freed slots.
        for i in (0..64).step_by(2) {
            assert!(table.insert(i, i + 1).1);
        }
        assert_eq!(table.len(), 64);
        assert_eq!(table.get(&4), Some(&5));
    }

    #[test]
    fn pathological_hasher_falls_back_to_overflow() {
        let mut table: HopscotchHash<i32, i32, BuildConstantHasher> =
            HopscotchHash::with_hasher(BuildConstantHasher);
        for i in 0..200 {
            assert!(table.insert(i, i * 2).1);
        }
        assert_eq!(table.len(), 200);
        assert!(table.overflow_len() > 0, "expected the overflow list to be used");
        for i in 0..200 {
            assert_eq!(table.get(&i), Some(&(i * 2)));
        }
        assert_eq!(collect_keys(&table), (0..200).collect::<BTreeSet<i32>>());
        // Removal must work for overflow entries too.
        for i in 0..200 {
            assert_eq!(table.remove(&i), Some(i * 2));
        }
        assert_eq!(table.len(), 0);
        assert_eq!(table.overflow_len(), 0);
    }

    #[test]
    fn mixing_hasher_handles_high_bit_only_keys() {
        let mut table: HopscotchHash<i64, i64, BuildMixingHasher> =
            HopscotchHash::with_hasher(BuildMixingHasher);
        for i in 0..1_000i64 {
            table.insert(i << 20, i);
        }
        assert_eq!(table.len(), 1_000);
        for i in 0..1_000i64 {
            assert_eq!(table.get(&(i << 20)), Some(&i));
        }
    }

    #[test]
    fn reserve_avoids_rehashing() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::with_capacity(1_000);
        let buckets = table.bucket_count();
        assert!(buckets >= 1_000);
        for i in 0..1_000 {
            table.insert(i, i);
        }
        assert_eq!(table.bucket_count(), buckets);
    }

    #[test]
    fn clear_keeps_capacity() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::new();
        for i in 0..100 {
            table.insert(i, i);
        }
        let buckets = table.bucket_count();
        table.clear();
        assert_eq!(table.len(), 0);
        assert_eq!(table.bucket_count(), buckets);
        assert_eq!(table.first_pos(), table.end_pos());
        assert!(table.find(&5).is_none());
        table.insert(5, 5);
        assert_eq!(table.get(&5), Some(&5));
    }

    #[test]
    fn neighbourhood_invariant_holds() {
        let mut table: HopscotchHash<i32, i32> = HopscotchHash::new();
        for i in 0..500 {
            table.insert(i * 3, i);
        }
        // Every stored entry must be reachable from its own home bucket bitmap.
        for slot in 0..table.slots() {
            if let Some((key, _)) = table.buckets()[slot].entry() {
                let home = table.home_of(key);
                assert!(slot >= home, "entry stored before its home bucket");
                let offset = slot - home;
                assert!(offset < NEIGHBOURHOOD_SIZE, "entry outside neighbourhood");
                assert_ne!(
                    table.buckets()[home].neighbourhood() & (1u32 << offset),
                    0,
                    "neighbourhood bit not set for slot {slot}"
                );
            }
        }
    }
}

