//! `tsl::hopscotch_map` translated to Rust.
//!
//! [`HopscotchMap`] is the user-facing wrapper around
//! [`HopscotchHash`](super::hopscotch_hash::HopscotchHash).  It keeps the shape
//! of the C++ container — unique keys, `insert` taking a pair and reporting
//! whether it inserted, `equal_range` handing back a pair of iterators — while
//! also implementing the usual Rust conveniences ([`Iterator`],
//! [`IntoIterator`], [`Extend`], [`FromIterator`]).
//!
//! ```text
//! C++                                     Rust
//! tsl::hopscotch_map<int, int> m;          let mut m: HopscotchMap<i32, i32> = HopscotchMap::new();
//! m.insert({k, v});                        m.insert((k, v));
//! auto r = m.equal_range(k);               let r = m.equal_range(&k);
//! for (auto it = r.first; it != r.second;  let mut it = r.first;
//!      ++it) { ... }                       while it != r.second { ...; it.increment(); }
//! ```

#![allow(dead_code)]

use std::fmt;
use std::hash::{BuildHasher, Hash};
use std::iter::FromIterator;

use super::hash::BuildIdentityHasher;
use super::hopscotch_hash::{HopscotchHash, Pos};

/// A hash map with unique keys, backed by hopscotch hashing.
pub struct HopscotchMap<K, V, S = BuildIdentityHasher> {
    table: HopscotchHash<K, V, S>,
}

impl<K, V> HopscotchMap<K, V, BuildIdentityHasher>
where
    K: Hash + Eq,
{
    /// An empty map; no buckets are allocated until the first insertion.
    pub fn new() -> HopscotchMap<K, V, BuildIdentityHasher> {
        HopscotchMap {
            table: HopscotchHash::new(),
        }
    }

    /// An empty map able to hold `capacity` entries without rehashing.
    pub fn with_capacity(capacity: usize) -> HopscotchMap<K, V, BuildIdentityHasher> {
        HopscotchMap {
            table: HopscotchHash::with_capacity(capacity),
        }
    }
}

impl<K, V> Default for HopscotchMap<K, V, BuildIdentityHasher>
where
    K: Hash + Eq,
{
    fn default() -> HopscotchMap<K, V, BuildIdentityHasher> {
        HopscotchMap::new()
    }
}

impl<K, V, S> HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    /// An empty map using `hash_builder`.
    pub fn with_hasher(hash_builder: S) -> HopscotchMap<K, V, S> {
        HopscotchMap {
            table: HopscotchHash::with_hasher(hash_builder),
        }
    }

    /// An empty map using `hash_builder`, sized for `capacity` entries.
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> HopscotchMap<K, V, S> {
        HopscotchMap {
            table: HopscotchHash::with_capacity_and_hasher(capacity, hash_builder),
        }
    }

    /// Number of stored entries — C++ `size()`.
    pub fn len(&self) -> usize {
        self.table.len()
    }

    /// True when the map stores no entry — C++ `empty()`.
    pub fn is_empty(&self) -> bool {
        self.table.is_empty()
    }

    /// Number of home buckets — C++ `bucket_count()`.
    pub fn bucket_count(&self) -> usize {
        self.table.bucket_count()
    }

    /// Entries that fit before the next rehash.
    pub fn capacity(&self) -> usize {
        self.table.capacity()
    }

    /// C++ `load_factor()`.
    pub fn load_factor(&self) -> f32 {
        self.table.load_factor()
    }

    /// C++ `max_load_factor()`.
    pub fn max_load_factor(&self) -> f32 {
        self.table.max_load_factor()
    }

    /// C++ `max_load_factor(float)`.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        self.table.set_max_load_factor(max_load_factor);
    }

    /// C++ `reserve()`: makes room for `additional` further entries.
    pub fn reserve(&mut self, additional: usize) {
        self.table.reserve(additional);
    }

    /// C++ `rehash()`: resizes so `min_entries` entries fit.
    pub fn rehash(&mut self, min_entries: usize) {
        self.table.rehash(min_entries);
    }

    /// C++ `clear()`.
    pub fn clear(&mut self) {
        self.table.clear();
    }

    /// The map's hash builder.
    pub fn hasher(&self) -> &S {
        self.table.hasher()
    }

    /// Inserts a key/value pair, leaving an existing equal key untouched.
    ///
    /// This is C++ `insert(std::pair<K, V>)`; the returned flag is that
    /// `std::pair<iterator, bool>::second`, and the [`Pos`] is where the entry
    /// for the key lives (pass it to [`iter_at`](Self::iter_at) for an
    /// iterator).
    pub fn insert(&mut self, value: (K, V)) -> (Pos, bool) {
        let (key, value) = value;
        self.table.insert(key, value)
    }

    /// C++ `insert_or_assign()`: inserts, or overwrites an existing value.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> (Pos, bool) {
        self.table.insert_or_assign(key, value)
    }

    /// Removes `key`, returning its value — C++ `erase()`.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        self.table.remove(key)
    }

    /// Removes `key`, returning the whole pair.
    pub fn remove_entry(&mut self, key: &K) -> Option<(K, V)> {
        self.table.remove_entry(key)
    }

    /// The value stored for `key` — C++ `at()`/`find()`.
    pub fn get(&self, key: &K) -> Option<&V> {
        self.table.get(key)
    }

    /// A mutable reference to the value stored for `key`.
    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        self.table.get_mut(key)
    }

    /// The key and value stored for `key`.
    pub fn get_key_value(&self, key: &K) -> Option<(&K, &V)> {
        self.table.get_key_value(key)
    }

    /// C++ `count()`: `1` when the key is present, `0` otherwise.  Unique keys
    /// mean it can never exceed one.
    pub fn count(&self, key: &K) -> usize {
        if self.table.contains_key(key) {
            1
        } else {
            0
        }
    }

    /// C++ `contains()`.
    pub fn contains_key(&self, key: &K) -> bool {
        self.table.contains_key(key)
    }

    /// C++ `find()`: an iterator to the entry, or `None` when absent.
    ///
    /// [`find_iter`](Self::find_iter) is the closer analogue when the C++ code
    /// compares the result against `end()`.
    pub fn find(&self, key: &K) -> Option<Iter<'_, K, V, S>> {
        self.table.find(key).map(|pos| Iter::new(&self.table, pos))
    }

    /// C++ `find()`, returning [`end`](Self::end) when the key is absent.
    pub fn find_iter(&self, key: &K) -> Iter<'_, K, V, S> {
        match self.table.find(key) {
            Some(pos) => Iter::new(&self.table, pos),
            None => self.end(),
        }
    }

    /// C++ `equal_range()`: the half-open iterator range covering `key`.
    ///
    /// Because keys are unique the range holds exactly one element when the key
    /// is present and is empty otherwise — so counting the elements between
    /// `first` and `second` yields `1` or `0`.
    pub fn equal_range(&self, key: &K) -> EqualRange<'_, K, V, S> {
        match self.table.find(key) {
            Some(pos) => {
                let first = Iter::new(&self.table, pos);
                let mut second = first;
                second.increment();
                EqualRange { first, second }
            }
            None => {
                let end = self.end();
                EqualRange {
                    first: end,
                    second: end,
                }
            }
        }
    }

    /// C++ `begin()`.
    pub fn begin(&self) -> Iter<'_, K, V, S> {
        Iter::new(&self.table, self.table.first_pos())
    }

    /// C++ `end()`.
    pub fn end(&self) -> Iter<'_, K, V, S> {
        Iter::new(&self.table, self.table.end_pos())
    }

    /// An iterator anchored at `pos`, as returned by [`insert`](Self::insert).
    pub fn iter_at(&self, pos: Pos) -> Iter<'_, K, V, S> {
        Iter::new(&self.table, pos)
    }

    /// Iterates over every key/value pair, in unspecified order.
    pub fn iter(&self) -> Iter<'_, K, V, S> {
        self.begin()
    }

    /// Iterates over every key, in unspecified order.
    pub fn keys(&self) -> Keys<'_, K, V, S> {
        Keys { inner: self.iter() }
    }

    /// Iterates over every value, in unspecified order.
    pub fn values(&self) -> Values<'_, K, V, S> {
        Values { inner: self.iter() }
    }

    /// The underlying table, for introspection.
    pub fn table(&self) -> &HopscotchHash<K, V, S> {
        &self.table
    }
}

impl<K, V, S> fmt::Debug for HopscotchMap<K, V, S>
where
    K: Hash + Eq + fmt::Debug,
    V: fmt::Debug,
    S: BuildHasher,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter()).finish()
    }
}

impl<K, V, S> Clone for HopscotchMap<K, V, S>
where
    K: Hash + Eq + Clone,
    V: Clone,
    S: BuildHasher + Clone,
{
    fn clone(&self) -> HopscotchMap<K, V, S> {
        let mut cloned =
            HopscotchMap::with_capacity_and_hasher(self.len(), self.table.hasher().clone());
        for (key, value) in self.iter() {
            cloned.insert((key.clone(), value.clone()));
        }
        cloned
    }
}

impl<K, V, S> PartialEq for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    V: PartialEq,
    S: BuildHasher,
{
    fn eq(&self, other: &HopscotchMap<K, V, S>) -> bool {
        self.len() == other.len()
            && self
                .iter()
                .all(|(key, value)| other.get(key).map_or(false, |stored| stored == value))
    }
}

impl<K, V, S> Eq for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    V: Eq,
    S: BuildHasher,
{
}

impl<K, V, S> Extend<(K, V)> for HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    fn extend<I: IntoIterator<Item = (K, V)>>(&mut self, iter: I) {
        let iter = iter.into_iter();
        self.reserve(iter.size_hint().0);
        for pair in iter {
            self.insert(pair);
        }
    }
}

impl<K, V> FromIterator<(K, V)> for HopscotchMap<K, V, BuildIdentityHasher>
where
    K: Hash + Eq,
{
    fn from_iter<I: IntoIterator<Item = (K, V)>>(iter: I) -> HopscotchMap<K, V, BuildIdentityHasher> {
        let mut map = HopscotchMap::new();
        map.extend(iter);
        map
    }
}

impl<'a, K, V, S> IntoIterator for &'a HopscotchMap<K, V, S>
where
    K: Hash + Eq,
    S: BuildHasher,
{
    type Item = (&'a K, &'a V);
    type IntoIter = Iter<'a, K, V, S>;

    fn into_iter(self) -> Iter<'a, K, V, S> {
        self.iter()
    }
}

/// A borrowing iterator over a [`HopscotchMap`].
///
/// It doubles as the translation of a C++ `const_iterator`: it is `Copy`,
/// compares by position ([`PartialEq`]) and can be stepped in place with
/// [`increment`](Iter::increment), which is how `++it` is spelled here.
pub struct Iter<'a, K, V, S = BuildIdentityHasher> {
    table: &'a HopscotchHash<K, V, S>,
    pos: Pos,
}

impl<'a, K, V, S> Iter<'a, K, V, S> {
    fn new(table: &'a HopscotchHash<K, V, S>, pos: Pos) -> Iter<'a, K, V, S> {
        Iter { table, pos }
    }

    /// The position this iterator points at.
    pub fn pos(&self) -> Pos {
        self.pos
    }

    /// True when the iterator is the map's `end()`.
    pub fn is_end(&self) -> bool {
        self.pos >= self.table.end_pos()
    }

    /// C++ `++it`: steps to the next entry, saturating at `end()`.
    pub fn increment(&mut self) {
        self.pos = self.table.pos_after(self.pos);
    }

    /// C++ `*it`: the pair the iterator points at, or `None` at `end()`.
    pub fn get(&self) -> Option<(&'a K, &'a V)> {
        self.table.entry_at(self.pos).map(|entry| (&entry.0, &entry.1))
    }

    /// C++ `it->first`.
    pub fn key(&self) -> Option<&'a K> {
        self.get().map(|(key, _)| key)
    }

    /// C++ `it->second`.
    pub fn value(&self) -> Option<&'a V> {
        self.get().map(|(_, value)| value)
    }
}

impl<'a, K, V, S> Clone for Iter<'a, K, V, S> {
    fn clone(&self) -> Iter<'a, K, V, S> {
        Iter {
            table: self.table,
            pos: self.pos,
        }
    }
}

impl<'a, K, V, S> Copy for Iter<'a, K, V, S> {}

impl<'a, K, V, S> PartialEq for Iter<'a, K, V, S> {
    fn eq(&self, other: &Iter<'a, K, V, S>) -> bool {
        std::ptr::eq(self.table, other.table) && self.pos == other.pos
    }
}

impl<'a, K, V, S> Eq for Iter<'a, K, V, S> {}

impl<'a, K, V, S> fmt::Debug for Iter<'a, K, V, S> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Iter").field("pos", &self.pos).finish()
    }
}

impl<'a, K, V, S> Iterator for Iter<'a, K, V, S> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<(&'a K, &'a V)> {
        let table = self.table;
        let entry = table.entry_at(self.pos)?;
        self.pos = table.pos_after(self.pos);
        Some((&entry.0, &entry.1))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (0, Some(self.table.len()))
    }
}

/// The pair of iterators returned by
/// [`HopscotchMap::equal_range`], mirroring `std::pair<iterator, iterator>`.
pub struct EqualRange<'a, K, V, S = BuildIdentityHasher> {
    /// C++ `range.first`.
    pub first: Iter<'a, K, V, S>,
    /// C++ `range.second`.
    pub second: Iter<'a, K, V, S>,
}

impl<'a, K, V, S> EqualRange<'a, K, V, S> {
    /// Number of entries in the range: `0` or `1` for a unique-key map.
    pub fn len(&self) -> usize {
        let mut count = 0;
        let mut it = self.first;
        while it != self.second {
            count += 1;
            it.increment();
        }
        count
    }

    /// True when the key was absent.
    pub fn is_empty(&self) -> bool {
        self.first == self.second
    }
}

impl<'a, K, V, S> Clone for EqualRange<'a, K, V, S> {
    fn clone(&self) -> EqualRange<'a, K, V, S> {
        EqualRange {
            first: self.first,
            second: self.second,
        }
    }
}

impl<'a, K, V, S> Copy for EqualRange<'a, K, V, S> {}

impl<'a, K, V, S> Iterator for EqualRange<'a, K, V, S> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<(&'a K, &'a V)> {
        if self.first == self.second {
            return None;
        }
        let item = self.first.get();
        self.first.increment();
        item
    }
}

/// Iterator over a map's keys.
pub struct Keys<'a, K, V, S = BuildIdentityHasher> {
    inner: Iter<'a, K, V, S>,
}

impl<'a, K, V, S> Iterator for Keys<'a, K, V, S> {
    type Item = &'a K;

    fn next(&mut self) -> Option<&'a K> {
        self.inner.next().map(|(key, _)| key)
    }
}

/// Iterator over a map's values.
pub struct Values<'a, K, V, S = BuildIdentityHasher> {
    inner: Iter<'a, K, V, S>,
}

impl<'a, K, V, S> Iterator for Values<'a, K, V, S> {
    type Item = &'a V;

    fn next(&mut self) -> Option<&'a V> {
        self.inner.next().map(|(_, value)| value)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;

    /// The exact loop the C++ program runs, as a reusable helper.
    fn count_in_equal_range(map: &HopscotchMap<i32, i32>, key: i32) -> i32 {
        let range = map.equal_range(&key);
        let mut num_in_range = 0;
        let mut it = range.first;
        while it != range.second {
            num_in_range += 1;
            it.increment();
        }
        num_in_range
    }

    fn build(count: i32) -> HopscotchMap<i32, i32> {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        let mut i = 0;
        while i < count {
            map.insert((i, i.wrapping_mul(12)));
            i += 1;
        }
        map
    }

    #[test]
    fn equal_range_on_present_key_holds_one_element() {
        let map = build(15);
        for key in 0..15 {
            assert_eq!(count_in_equal_range(&map, key), 1, "key {key}");
            let range = map.equal_range(&key);
            assert!(!range.is_empty());
            assert_eq!(range.len(), 1);
            assert_eq!(range.first.get(), Some((&key, &(key * 12))));
        }
    }

    #[test]
    fn equal_range_on_absent_key_is_empty() {
        let map = build(15);
        for key in [-1, 15, 16, 1000, i32::MIN, i32::MAX] {
            assert_eq!(count_in_equal_range(&map, key), 0, "key {key}");
            let range = map.equal_range(&key);
            assert!(range.is_empty());
            assert_eq!(range.len(), 0);
            assert_eq!(range.first, map.end());
            assert_eq!(range.second, map.end());
        }
    }

    #[test]
    fn equal_range_on_empty_map_is_empty() {
        let map = build(0);
        assert!(map.is_empty());
        assert_eq!(count_in_equal_range(&map, 0), 0);
        assert_eq!(map.begin(), map.end());
    }

    /// The complete input/output contract of the ported program.
    #[test]
    fn program_contract_for_every_interesting_count() {
        for count in [-1000, -2, -1, 0, 1, 2, 3, 4, 5, 15, 16, 31, 32, 33, 100, 5000] {
            let map = build(count);
            let expected = if count >= 1 { 1 } else { 0 };
            assert_eq!(
                count_in_equal_range(&map, count / 2),
                expected,
                "count {count}"
            );
        }
    }

    #[test]
    fn iteration_visits_every_entry_once() {
        let map = build(1000);
        let collected: BTreeMap<i32, i32> = map.iter().map(|(&k, &v)| (k, v)).collect();
        assert_eq!(collected.len(), 1000);
        for (key, value) in &collected {
            assert_eq!(*value, key * 12);
        }
        assert_eq!(map.keys().count(), 1000);
        assert_eq!(map.values().count(), 1000);
    }

    #[test]
    fn insert_reports_duplicates() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
        assert!(map.insert((1, 12)).1);
        assert!(!map.insert((1, 99)).1);
        assert_eq!(map.get(&1), Some(&12));
        assert_eq!(map.count(&1), 1);
        assert_eq!(map.count(&2), 0);
        assert_eq!(map.len(), 1);
    }

    #[test]
    fn insert_position_matches_find() {
        let mut map: HopscotchMap<i32, i32> = HopscotchMap::with_capacity(64);
        let (pos, inserted) = map.insert((42, 504));
        assert!(inserted);
        assert_eq!(map.iter_at(pos), map.find_iter(&42));
        assert_eq!(map.iter_at(pos).get(), Some((&42, &504)));
    }

    #[test]
    fn find_and_remove() {
        let mut map = build(50);
        assert!(map.find(&10).is_some());
        assert_eq!(map.find(&10).and_then(|it| it.value()), Some(&120));
        assert!(map.find(&50).is_none());
        assert_eq!(map.find_iter(&50), map.end());
        assert_eq!(map.remove(&10), Some(120));
        assert_eq!(map.remove(&10), None);
        assert_eq!(map.len(), 49);
        assert_eq!(count_in_equal_range(&map, 10), 0);
    }

    #[test]
    fn iterators_from_different_maps_never_compare_equal() {
        let left = build(4);
        let right = build(4);
        assert_ne!(left.end(), right.end());
        assert_eq!(left.end(), left.end());
    }

    #[test]
    fn derived_traits_behave() {
        let map = build(8);
        let cloned = map.clone();
        assert_eq!(map, cloned);
        let mut other = cloned.clone();
        other.insert((100, 1));
        assert_ne!(map, other);
        assert!(format!("{map:?}").starts_with('{'));

        let from_iter: HopscotchMap<i32, i32> = (0..8).map(|i| (i, i * 12)).collect();
        assert_eq!(map, from_iter);
    }

    #[test]
    fn equal_range_is_also_a_rust_iterator() {
        let map = build(15);
        let items: Vec<(i32, i32)> = map
            .equal_range(&7)
            .map(|(&key, &value)| (key, value))
            .collect();
        assert_eq!(items, vec![(7, 84)]);
        assert_eq!(map.equal_range(&99).count(), 0);
    }
}

