//! A reimplementation of `std::stoi`.
//!
//! `std::stoi` is not `str::parse::<i32>()`.  libstdc++ implements it on top of
//! `std::strtol`, which means it
//!
//! 1. skips leading whitespace,
//! 2. accepts a single optional `+`/`-` sign,
//! 3. consumes decimal digits only (so `"0x10"` parses as `0`, stopping at
//!    `'x'`, and `"010"` is ten, not eight),
//! 4. **ignores trailing garbage** — `"3x"` parses as `3`,
//! 5. throws `std::invalid_argument` when not a single digit was consumed, and
//! 6. throws `std::out_of_range` when the value does not fit in an `int` (or
//!    already overflowed the intermediate `long`).
//!
//! `str::parse` would instead reject `" 7"`, `"+4"` and `"3x"` outright, so the
//! port needs this shim to stay behaviour-compatible.

#![allow(dead_code)]

use std::fmt;

/// `int` in the C++ program is a 32-bit `i32`.
const INT_MIN: i64 = i32::MIN as i64;
const INT_MAX: i64 = i32::MAX as i64;

/// Magnitude limit of the intermediate `long` (64-bit on LP64 targets); one past
/// `LONG_MAX` because `-(LONG_MIN)` is exactly this value.
const LONG_MAGNITUDE_LIMIT: u128 = i64::MAX as u128 + 1;

/// The C++ exception `std::stoi` would have thrown.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoiError {
    /// `std::invalid_argument`: no digits could be converted.
    InvalidArgument,
    /// `std::out_of_range`: the value does not fit in an `int`.
    OutOfRange,
}

impl StoiError {
    /// The mangled-free C++ type name libstdc++ prints when the exception
    /// escapes `main`.
    pub fn cxx_type_name(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// The `what()` string, which libstdc++ sets to the function name.
    pub fn what(self) -> &'static str {
        "stoi"
    }
}

impl fmt::Display for StoiError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.what())
    }
}

impl std::error::Error for StoiError {}

/// True for the characters `std::isspace` accepts in the "C" locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// `std::stoi(text)`.
pub fn stoi(text: &str) -> Result<i32, StoiError> {
    stoi_with_pos(text).map(|(value, _)| value)
}

/// `std::stoi(text, &pos)`: also reports how many bytes were consumed,
/// including any leading whitespace and the sign.
pub fn stoi_with_pos(text: &str) -> Result<(i32, usize), StoiError> {
    let bytes = text.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_space(bytes[index]) {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(&b'-') => {
            index += 1;
            true
        }
        Some(&b'+') => {
            index += 1;
            false
        }
        _ => false,
    };

    let first_digit = index;
    let mut magnitude: u128 = 0;
    let mut long_overflow = false;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        if !long_overflow {
            magnitude = magnitude * 10 + u128::from(bytes[index] - b'0');
            if magnitude > LONG_MAGNITUDE_LIMIT {
                // `strtol` would have saturated and set ERANGE here; keep
                // consuming digits so `pos` still lands past the number.
                long_overflow = true;
            }
        }
        index += 1;
    }

    if index == first_digit {
        // `strtol` converted nothing at all.
        return Err(StoiError::InvalidArgument);
    }
    if long_overflow {
        return Err(StoiError::OutOfRange);
    }

    let value = if negative {
        if magnitude > LONG_MAGNITUDE_LIMIT {
            return Err(StoiError::OutOfRange);
        }
        -(magnitude as i128)
    } else {
        if magnitude > i64::MAX as u128 {
            return Err(StoiError::OutOfRange);
        }
        magnitude as i128
    };

    if value < INT_MIN as i128 || value > INT_MAX as i128 {
        return Err(StoiError::OutOfRange);
    }
    Ok((value as i32, index))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_decimal_numbers() {
        assert_eq!(stoi("0"), Ok(0));
        assert_eq!(stoi("1"), Ok(1));
        assert_eq!(stoi("15"), Ok(15));
        assert_eq!(stoi("000123"), Ok(123));
        assert_eq!(stoi("010"), Ok(10), "base 10, not octal");
    }

    #[test]
    fn signs_are_accepted() {
        assert_eq!(stoi("+4"), Ok(4));
        assert_eq!(stoi("-4"), Ok(-4));
        assert_eq!(stoi("-0"), Ok(0));
    }

    #[test]
    fn leading_whitespace_is_skipped() {
        assert_eq!(stoi(" 7"), Ok(7));
        assert_eq!(stoi("\t\n\r\u{0b}\u{0c} 7"), Ok(7));
        assert_eq!(stoi("  -7"), Ok(-7));
    }

    #[test]
    fn trailing_garbage_is_ignored() {
        assert_eq!(stoi("3x"), Ok(3));
        assert_eq!(stoi("12abc"), Ok(12));
        assert_eq!(stoi("5 5"), Ok(5));
        assert_eq!(stoi("0x10"), Ok(0), "conversion stops at 'x'");
        assert_eq!(stoi("7."), Ok(7));
        assert_eq!(stoi("1,000"), Ok(1));
        assert_eq!(stoi("4 "), Ok(4));
    }

    #[test]
    fn nothing_to_convert_is_invalid_argument() {
        for text in ["", " ", "\t", "abc", "x1", "-", "+", " - ", "--5", "+-5", ".5", "٣"] {
            assert_eq!(
                stoi(text),
                Err(StoiError::InvalidArgument),
                "input {text:?}"
            );
        }
    }

    #[test]
    fn int_boundaries() {
        assert_eq!(stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(stoi("-2147483648"), Ok(i32::MIN));
        assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("99999999999999999999"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-99999999999999999999"), Err(StoiError::OutOfRange));
        // Long-range overflow reports out_of_range as well.
        assert_eq!(stoi("9223372036854775808"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-9223372036854775808"), Err(StoiError::OutOfRange));
        assert_eq!(
            stoi("123456789012345678901234567890123456789012345678901234567890"),
            Err(StoiError::OutOfRange)
        );
    }

    #[test]
    fn out_of_range_beats_trailing_garbage() {
        assert_eq!(stoi("2147483648abc"), Err(StoiError::OutOfRange));
    }

    #[test]
    fn reported_position() {
        assert_eq!(stoi_with_pos("15"), Ok((15, 2)));
        assert_eq!(stoi_with_pos("  -42rest"), Ok((-42, 5)));
        assert_eq!(stoi_with_pos("+0)"), Ok((0, 2)));
    }

    #[test]
    fn error_metadata_matches_libstdcxx() {
        assert_eq!(
            StoiError::InvalidArgument.cxx_type_name(),
            "std::invalid_argument"
        );
        assert_eq!(StoiError::OutOfRange.cxx_type_name(), "std::out_of_range");
        assert_eq!(StoiError::OutOfRange.what(), "stoi");
    }
}

