//! Reproductions of the libstdc++ runtime behaviour the original program could
//! trigger.
//!
//! The C++ `main` catches nothing, so an exception thrown by `std::stoi` — or by
//! `std::string`'s constructor when `argv[2]` is a null pointer — escapes into
//! `std::terminate`.  libstdc++'s default terminate handler prints
//!
//! ```text
//! terminate called after throwing an instance of 'std::invalid_argument'
//!   what():  stoi
//! ```
//!
//! to standard error (note the two spaces after `what():`) and then calls
//! `std::abort`, killing the process with `SIGABRT` — shell exit status 134.
//! [`terminate_uncaught_exception`] does exactly that so the port fails the same
//! way, byte for byte, as the binary it replaces.

#![allow(dead_code)]

use std::io::Write;
use std::process;

/// Prints libstdc++'s uncaught-exception message and aborts.
pub fn terminate_uncaught_exception(cxx_type_name: &str, what: &str) -> ! {
    let mut stderr = std::io::stderr();
    // Written as one buffer so the message cannot interleave with other output.
    let message = format!(
        "terminate called after throwing an instance of '{}'\n  what():  {}\n",
        cxx_type_name, what
    );
    let _ = stderr.write_all(message.as_bytes());
    let _ = stderr.flush();
    process::abort()
}

#[cfg(test)]
mod tests {
    /// The message layout is asserted here because the abort path itself cannot
    /// be exercised in-process.
    #[test]
    fn message_layout_has_two_spaces_after_what() {
        let message = format!(
            "terminate called after throwing an instance of '{}'\n  what():  {}\n",
            "std::invalid_argument", "stoi"
        );
        assert_eq!(
            message,
            "terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi\n"
        );
    }
}

