//! `argc`/`argv` plumbing that behaves like the C++ program's.
//!
//! C's `argv` is a null-terminated array, so reading `argv[2]` when only two
//! arguments were passed yields a null pointer rather than an out-of-bounds
//! access.  Handing that pointer to `std::string` throws `std::logic_error`,
//! which is what the original binary dies with for `./test15 --a`.  [`at`]
//! reproduces that, so the port matches even on the failure path.

#![allow(dead_code)]

use super::runtime;

/// The `std::logic_error` message libstdc++ produces for `std::string(nullptr)`.
const NULL_STRING_WHAT: &str = "basic_string::_S_construct null not valid";

/// The process arguments, including `argv[0]`; the length is C++'s `argc`.
///
/// Uses [`std::env::args_os`] rather than `args` so that arguments which are not
/// valid UTF-8 are replaced lossily instead of panicking — the C++ program
/// happily accepts arbitrary bytes.
pub fn collect() -> Vec<String> {
    std::env::args_os()
        .map(|arg| arg.to_string_lossy().into_owned())
        .collect()
}

/// `std::string(argv[index])`.
///
/// Reading past the last argument is the null-pointer case, which terminates
/// the process exactly like the C++ original instead of panicking.
pub fn at(argv: &[String], index: usize) -> &str {
    match argv.get(index) {
        Some(argument) => argument.as_str(),
        None => runtime::terminate_uncaught_exception("std::logic_error", NULL_STRING_WHAT),
    }
}

/// `argv[index]` if present, without the C++ null-pointer behaviour.
pub fn get(argv: &[String], index: usize) -> Option<&str> {
    argv.get(index).map(|argument| argument.as_str())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn present_arguments_are_returned_verbatim() {
        let argv = vec!["./test15".to_string(), "--a".to_string(), "5".to_string()];
        assert_eq!(at(&argv, 0), "./test15");
        assert_eq!(at(&argv, 1), "--a");
        assert_eq!(at(&argv, 2), "5");
        assert_eq!(get(&argv, 3), None);
    }

    #[test]
    fn collect_includes_the_program_name() {
        assert!(!collect().is_empty(), "argv[0] must always be present");
    }
}

