    /// Number of entries stored.
    pub fn len(&self) -> usize {
        self.len
    }

    /// True when no entry is stored.
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    /// Number of home buckets (a power of two, or zero when unallocated).
    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    /// Number of slots in the bucket array, including the trailing overflow
    /// slack that keeps neighbourhoods from wrapping.
    pub fn slots(&self) -> usize {
        self.buckets.len()
    }

    /// Number of entries that did not fit into any neighbourhood.
    pub fn overflow_len(&self) -> usize {
        self.overflow.len()
    }

    /// Number of entries the table can hold before it grows.
    pub fn capacity(&self) -> usize {
        self.grow_at
    }

    /// `len / bucket_count`, or `0.0` while unallocated.
    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.len as f32 / self.bucket_count as f32
        }
    }

    /// The load factor above which the table doubles.
    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    /// Sets the growth threshold, rehashing immediately if already exceeded.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        assert!(
            max_load_factor > 0.0 && max_load_factor <= 1.0,
            "max_load_factor must be in (0.0, 1.0]"
        );
        self.max_load_factor = max_load_factor;
        self.grow_at = grow_threshold(self.bucket_count, max_load_factor);
        if self.bucket_count != 0 && self.len > self.grow_at {
            self.reserve(self.len);
        }
    }

