//! The `tsl` namespace: a pure-`std` Rust translation of the parts of the
//! [hopscotch-map] C++ library that the ported program uses.
//!
//! [`HopscotchMap`] is the counterpart of `tsl::hopscotch_map`; the table that
//! implements it lives in [`hopscotch_hash`], and the hashers that stand in for
//! `std::hash` live in [`hash`].
//!
//! [hopscotch-map]: https://github.com/Tessil/hopscotch-map

#![allow(dead_code)]

pub mod hash;
pub mod hopscotch_hash;
pub mod hopscotch_map;

pub use self::hash::{BuildIdentityHasher, BuildMixingHasher, IdentityHasher, MixingHasher};
pub use self::hopscotch_hash::{HopscotchHash, Pos, NEIGHBOURHOOD_SIZE};
pub use self::hopscotch_map::{EqualRange, HopscotchMap, Iter, Keys, Values};

//! Thin shims for the C++ standard-library behaviour the original program
//! depended on, kept separate from the container port in
//! [`tsl`](super::tsl).
//!
//! * [`string`] — `std::stoi`, whose `strtol`-based parsing differs from
//!   `str::parse`.
//! * [`argv`] — `argc`/`argv` access, including the null-pointer case.
//! * [`runtime`] — libstdc++'s uncaught-exception termination message.

#![allow(dead_code)]

pub mod argv;
pub mod runtime;
pub mod string;

pub use self::string::{stoi, stoi_with_pos, StoiError};
